		const ROW_ATTR = "data-dsh-bd-row";

		/** Marks this plugin's hidden file picker. */
		const PICKER_ATTR = "data-dsh-bd-picker";

		/** Present on the row while the panel is collapsed to its rail. */
		const NARROW_ATTR = "data-dsh-bd-narrow";

